#include <bits/stdc++.h>
using namespace std;

#define LL long long
#define ULL unsigned LL
#define fi first
#define se second
#define pb push_back
const int INF = 0x3f3f3f3f;

int px[10000], py[10000];
int head[10000], to[100000], ct[100000], w[100000], nt[100000];
int dist[10000], inQueue[10000];
int parent[10000], edgeId[10000];
int source, sink, edgeCount;

void addEdge(int u, int v, int flow, int cost) {
    to[edgeCount] = v; ct[edgeCount] = cost; w[edgeCount] = flow; nt[edgeCount] = head[u]; head[u] = edgeCount++;
    to[edgeCount] = u; ct[edgeCount] = -cost; w[edgeCount] = 0; nt[edgeCount] = head[v]; head[v] = edgeCount++;
}

void initGraph() {
    memset(head, -1, sizeof(head));
    edgeCount = 0;
}

bool spfa(int s, int t) {
    std::queue<int> q;
    memset(dist, 0x3f, sizeof(dist));
    memset(inQueue, 0, sizeof(inQueue));
    memset(parent, -1, sizeof(parent));
    dist[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        inQueue[u] = 0;
        for (int i = head[u]; i != -1; i = nt[i]) {
            if (w[i] > 0 && dist[to[i]] > dist[u] + ct[i]) {
                dist[to[i]] = dist[u] + ct[i];
                parent[to[i]] = u;
                edgeId[to[i]] = i;
                if (!inQueue[to[i]]) {
                    inQueue[to[i]] = 1;
                    q.push(to[i]);
                }
            }
        }
    }
    return dist[t] < 0x3f3f3f3f;
}

int minCostMaxFlow(int s, int t) {
    int totalCost = 0, totalFlow = 0;
    while (spfa(s, t)) {
        int flowAmount = INF;
        for (int i = t; i != s; i = parent[i]) {
            flowAmount = min(flowAmount, w[edgeId[i]]);
        }
        for (int i = t; i != s; i = parent[i]) {
            w[edgeId[i]] -= flowAmount;
            w[edgeId[i] ^ 1] += flowAmount;
        }
        totalFlow += flowAmount;
        totalCost += dist[t] * flowAmount;
    }
    return totalCost;
}

int main() {
    initGraph();
    int n, m, k, c, d;
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    source = 0; sink = n * 100 + 1;
    for (int i = 1; i <= 100; ++i)
        addEdge(i, sink, 100, 0);
    for (int i = 1, v; i <= k; ++i) {
        scanf("%d", &v);
        addEdge(source, (v - 1) * 100 + 1, 1, 0);
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j < 100; ++j) {
            addEdge((i - 1) * 100 + j, (i - 1) * 100 + j + 1, 100, c);
        }
    }
    for (int i = 1, u, v; i <= m; ++i) {
        scanf("%d%d", &u, &v);
        for (int j = 1; j < 100; ++j) {
            int fromIdx = (u - 1) * 100 + j;
            int toIdx = (v - 1) * 100 + j + 1;
            for (int k = 1; k <= 20; ++k) {
                addEdge(fromIdx, toIdx, 1, c + (k * k - (k - 1) * (k - 1)) * d);
            }
        }
        for (int j = 1; j < 100; ++j) {
            int fromIdx = (v - 1) * 100 + j;
            int toIdx = (u - 1) * 100 + j + 1;
            for (int k = 1; k <= 20; ++k) {
                addEdge(fromIdx, toIdx, 1, c + (k * k - (k - 1) * (k - 1)) * d);
            }
        }
    }
    printf("%d\n", minCostMaxFlow(source, sink));
    return 0;
}
